using UnityEngine;using DG.Tweening;using LWS.TruckSports;
namespace LWS.TruckWifeCarrying {
public enum WifeState {Waiting,Racing,Dropped,Pickup,Penalty,Finished,DNF,Inactive}
public sealed class WifePair:MonoBehaviour {
 public WifeMatch match;public int slot;public SportsEventTruck driver,passenger;public Transform cradle;public LineRenderer[] straps;public Vector3 roofAnchor;public WifeState State{get;private set;}public int Checkpoint{get;private set;}public float Progress{get;private set;}public int Drops{get;private set;}public float FinishTime{get;private set;}=float.PositiveInfinity;public float PenaltyRemaining{get;private set;}public float Balance=>Vector3.Angle(driver.transform.up,passenger.transform.up);public bool Carried=>joint!=null;public Vector3 Incoming{get;private set;}
 ConfigurableJoint joint;Vector3 previous;float tipped,immobile,pickupAge,previousPassengerZ;Tween pickup;public Vector3 PickupOrigin{get;private set;}
 public void Prepare(bool active){RemoveJoint();pickup?.Kill();State=active?WifeState.Waiting:WifeState.Inactive;cradle.gameObject.SetActive(active);Checkpoint=Drops=0;Progress=5;FinishTime=float.PositiveInfinity;tipped=immobile=0;driver.slot=match.DriverRole(slot);passenger.slot=match.PassengerRole(slot);PrepareAppearance(driver);PrepareAppearance(passenger);driver.visuals.gameObject.SetActive(active);passenger.visuals.gameObject.SetActive(active);driver.Prepare(match.course.Spawn(slot),match.course.Rotation(5));passenger.Prepare(RoofPosition(),driver.body.rotation,false);driver.Power(false);driver.body.isKinematic=true;passenger.body.isKinematic=true;driver.body.detectCollisions=passenger.body.detectCollisions=active;driver.transform.SetPositionAndRotation(driver.body.position,driver.body.rotation);passenger.transform.SetPositionAndRotation(passenger.body.position,passenger.body.rotation);previous=driver.body.position;previousPassengerZ=passenger.body.position.z;}
 void PrepareAppearance(SportsEventTruck truck){if(truck.appearanceHost==null)return;var player=match.setup.players[truck.slot];truck.appearanceHost.Prepare(player.participantId,player.color);}
 public Vector3 RoofPosition()=>driver.body.position+driver.body.rotation*roofAnchor;public void Release(){if(State!=WifeState.Waiting)return;State=WifeState.Racing;driver.body.isKinematic=passenger.body.isKinematic=false;driver.Power(true);Attach();}
 void Attach(){RemoveJoint();driver.transform.SetPositionAndRotation(driver.body.position,driver.body.rotation);passenger.transform.SetPositionAndRotation(passenger.body.position,passenger.body.rotation);Physics.IgnoreCollision(driver.shape,passenger.shape,true);joint=passenger.gameObject.AddComponent<ConfigurableJoint>();joint.connectedBody=driver.body;joint.autoConfigureConnectedAnchor=false;joint.anchor=Vector3.zero;joint.connectedAnchor=roofAnchor;joint.xMotion=joint.yMotion=joint.zMotion=ConfigurableJointMotion.Locked;joint.angularXMotion=joint.angularYMotion=joint.angularZMotion=ConfigurableJointMotion.Limited;joint.lowAngularXLimit=new SoftJointLimit{limit=-27};joint.highAngularXLimit=new SoftJointLimit{limit=27};joint.angularYLimit=new SoftJointLimit{limit=18};joint.angularZLimit=new SoftJointLimit{limit=27};joint.rotationDriveMode=RotationDriveMode.Slerp;joint.slerpDrive=new JointDrive{positionSpring=11,positionDamper=3,maximumForce=20};joint.projectionMode=JointProjectionMode.PositionAndRotation;joint.projectionDistance=.1f;joint.projectionAngle=10;}
 void RemoveJoint(){if(joint!=null){Destroy(joint);joint=null;}if(driver!=null&&passenger!=null)Physics.IgnoreCollision(driver.shape,passenger.shape,false);}
 public bool Drop(string reason){if(State!=WifeState.Racing||joint==null)return false;RemoveJoint();State=WifeState.Dropped;Drops++;match.Dropped(this,reason+" balance="+Balance+" up="+Vector3.Dot(driver.transform.up,Vector3.up)+" gap="+Vector3.Distance(passenger.body.position,RoofPosition()));return true;}
 public void Step(Vector2 drive,Vector2 lean,bool brace,float dt){if(State==WifeState.Waiting||State==WifeState.Inactive||State==WifeState.DNF)return;if(State==WifeState.Finished){HoldBrakes();return;}if(State==WifeState.Penalty){HoldBrakes();PenaltyRemaining-=dt;if(PenaltyRemaining<=0)State=WifeState.Racing;return;}if(State==WifeState.Pickup){HoldBrakes();pickupAge+=dt;if(pickupAge>=1.2f){passenger.body.position=RoofPosition();passenger.body.rotation=driver.body.rotation;passenger.body.isKinematic=false;passenger.body.linearVelocity=driver.body.GetPointVelocity(passenger.body.position);Attach();State=WifeState.Penalty;PenaltyRemaining=5;match.Gate();}return;}
 driver.grip=1.2f*match.course.Grip(driver.body.position);driver.TickDrive(drive);Incoming=driver.body.linearVelocity;float speed=Incoming.magnitude;
 if(State==WifeState.Racing&&joint!=null){joint.targetRotation=Quaternion.identity;passenger.body.centerOfMass=Vector3.MoveTowards(passenger.body.centerOfMass,new Vector3(lean.x*.20f,.03f,lean.y*.20f),dt*.6f);joint.slerpDrive=new JointDrive{positionSpring=brace?29:11,positionDamper=brace?7:3,maximumForce=brace?32:20};var torque=driver.transform.right*lean.y*1.7f-driver.transform.forward*lean.x*1.7f;passenger.body.AddTorque(torque,ForceMode.Force);driver.body.AddTorque(-torque,ForceMode.Force);tipped=Vector3.Dot(driver.transform.up,Vector3.up)<.42f?tipped+dt:Mathf.Max(0,tipped-dt);if(tipped>.6f||Balance>48||Vector3.Distance(passenger.body.position,RoofPosition())>1)Drop("UNBALANCED");}
 if(State==WifeState.Dropped&&speed<1.6f&&Vector3.Distance(driver.body.position,passenger.body.position)<4.8f&&Vector3.Dot(driver.transform.up,Vector3.up)>.6f){PickupOrigin=driver.body.position;State=WifeState.Pickup;pickupAge=0;passenger.body.isKinematic=true;Physics.IgnoreCollision(driver.shape,passenger.shape,true);pickup?.Kill();pickup=passenger.transform.DOJump(RoofPosition(),1.1f,1,1.2f).SetEase(Ease.InOutSine).SetLink(gameObject);match.Pickup(this);}
 var p=driver.body.position;float current=match.course.Project(p,Progress,out float lateral);float before=Progress;if(Mathf.Abs(current-Progress)<8)Progress=current;while(Checkpoint<match.course.checkpoints.Length&&before<match.course.checkpoints[Checkpoint]&&Progress>=match.course.checkpoints[Checkpoint]){if(Mathf.Abs(lateral)>24)break;Checkpoint++;}float passengerProgress=match.course.Project(passenger.body.position,Progress,out float passengerLateral);if(State==WifeState.Racing&&joint!=null&&Checkpoint==match.course.checkpoints.Length&&Progress>=WifeCourse.Finish&&passengerProgress>=WifeCourse.Finish&&Mathf.Abs(lateral)<24&&Mathf.Abs(passengerLateral)<24){State=WifeState.Finished;FinishTime=match.Clock;match.Arrived(this);}previous=p;previousPassengerZ=passenger.body.position.z;
 immobile=speed<.2f&&drive.y>.3f?immobile+dt:0;if(p.y<match.course.Height(p)-8||Mathf.Abs(p.x)>130||Progress>WifeCourse.Finish+30||passenger.body.position.y<match.course.Height(passenger.body.position)-8||immobile>15)Fail();}
 void HoldBrakes(){driver.command=Vector2.zero;foreach(var wheel in driver.wheels){wheel.MotorTorque=0;wheel.BrakeTorque=driver.brakeTorque;wheel.SteerAngle=0;}}
 public void Fail(){if(State==WifeState.Finished||State==WifeState.Inactive)return;Debug.Log("WIFE_DNF pair="+slot+" p="+driver.body.position+" passenger="+passenger.body.position+" cp="+Checkpoint+" stranded="+immobile);State=WifeState.DNF;Stop();}
 void OnCollisionEnter(Collision c){if(State!=WifeState.Racing)return;float impact=0;for(int i=0;i<c.contactCount;i++)impact=Mathf.Max(impact,-Vector3.Dot(Incoming,c.GetContact(i).normal));if(impact>8)Drop("VIOLENT IMPACT");match.Impact(slot,Mathf.Max(impact,c.relativeVelocity.magnitude));}
 void LateUpdate(){if(straps==null)return;for(int i=0;i<straps.Length;i++){straps[i].enabled=joint!=null;if(joint==null)continue;var a=driver.transform.TransformPoint(roofAnchor+new Vector3(i==0?-.65f:.65f,-.1f,0));var b=passenger.transform.TransformPoint(new Vector3(i==0?-1:1,.35f,0));straps[i].SetPosition(0,a);straps[i].SetPosition(1,(a+b)*.5f+Vector3.down*.06f);straps[i].SetPosition(2,b);}}
 public void Stop(){pickup?.Kill();driver.Power(false);passenger.Power(false);if(!driver.body.isKinematic)driver.body.linearVelocity=driver.body.angularVelocity=Vector3.zero;if(!passenger.body.isKinematic)passenger.body.linearVelocity=passenger.body.angularVelocity=Vector3.zero;driver.body.isKinematic=passenger.body.isKinematic=true;driver.StopSound();}void OnDestroy(){pickup?.Kill();RemoveJoint();}
}
}
